# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
A=[['拉丁 amare → amicus','爱、喜欢 → 朋友；友好的']]
N=A+[['拉丁 in- + amicus → inimicus','不是朋友 → 敌人、敌对的']]
W=[
E('enemy','/ˈenəmi/','敌人；敌方；妨碍某事的东西','站在对立面、可能伤害你或破坏目标的一方。','拉丁 in-“不”+ amicus“朋友”形成 inimicus，经古法语 enemi 进入英语；现代拼写已经不能逐字对应原成分。',N+[['古法语 enemi → 英语 enemy','敌人；敌方']],'词源里的“非朋友”帮助解释历史结构，现代 enemy 却不包括所有陌生人：它通常带明确对立或危害。Lack of sleep is the enemy of concentration 是说睡眠不足会破坏专注力，不是真的把它当成人。','an enemy of；make enemies；the enemy；enemy territory。','opponent 可以只是比赛或辩论对手，未必怀有敌意；enemy 的对立通常更强。',('They were political opponents, but never personal enemies.','他们是政治对手，却从不是私下的仇敌。'),('Constant interruption is the enemy of deep concentration.','不断被打断是深入专注的大敌。'),sources=['https://www.etymonline.com/word/enemy','https://en.wiktionary.org/wiki/enemy']),
E('enmity','/ˈenməti/','敌意、仇怨〔较书面〕','关系里一直有一根刺，双方难以友好相处。','经古法语 enemite／enemistié，接拉丁 inimicitia“敌意”及通俗拉丁同族形式。可联系 enemy 理解，但不是现代英语简单给 enemy 加 -ity。',N+[['拉丁 inimicitia／通俗拉丁同族形式 → 古法语 enemistié','敌对关系、敌意'],['英语 enmity','敌意、仇怨']],'enemy 是敌对的人，enmity 是人和人之间的敌意。longstanding enmity 指延续很久的积怨；without enmity 表示没有怀着敌意。它通常比一次意见不合更深，也比口语 dislike 更正式。','enmity between；personal enmity；earn someone’s enmity。','rivalry 是竞争关系，可以互相尊重；enmity 更明确含敌意。',('There was no personal enmity between the two candidates.','两名候选人之间并没有私人仇怨。'),('The dispute created years of enmity between the families.','这场纠纷让两个家庭积下了多年的仇怨。'),sources=['https://www.etymonline.com/word/enmity','https://en.wiktionary.org/wiki/enmity']),
E('amicable','/ˈæmɪkəbl/','友好的、和睦的','有分歧也能好好说，不把事情弄成敌对。','来自晚期拉丁 amicabilis“友好的”，接 amicus“朋友”；英语保留了较明显的 amic- 形式。',A+[['晚期拉丁 amicabilis → 英语 amicable','友好的、和睦的']],'an amicable agreement 是双方心平气和达成的协议，an amicable separation 是分开时仍能友好处理。重点常在关系或处理方式，没有要求两个人仍然亲密，也没有说他们从来没有分歧。','an amicable agreement；amicable relations；an amicable settlement。','amiable 常形容一个人亲切好相处；amicable 常形容关系、讨论和解决方式和睦。这是常见搭配倾向，不是绝对语法禁令。',('They reached an amicable agreement about the shared garden.','他们就共用花园的安排友好地达成了协议。'),('The separation was amicable, and they remained in contact.','他们和平分开，之后仍保持联系。'),sources=['https://www.etymonline.com/word/amicable','https://www.merriam-webster.com/dictionary/amicable']),
E('amicably','/ˈæmɪkəbli/','友好地、和睦地','把问题摆到桌面上，好好谈、好好收场。','amicable 去末尾 e 加 -ly；副词描述分手、协商、解决纠纷等行为的方式。',A+[['英语 amicable → amicably','和睦的 → 以友好方式']],'settle amicably 是协商解决而不继续敌对，part amicably 是友好分开。这个词很适合“结果是分开或让步，但过程没有撕破脸”的场景。它评价处理方式，不保证所有人都得到了最想要的结果。','settle amicably；resolve amicably；part amicably。','amiably 多描述说话、微笑等亲切的举止；amicably 常描述双方如何处理关系或分歧。',('The neighbours resolved the problem amicably.','邻居们友好地解决了这个问题。'),('We agreed to end the project amicably.','我们同意友好地结束这个项目。'),sources=['https://en.wiktionary.org/wiki/amicably']),
E('amiable','/ˈeɪmiəbl/','亲切的、和善好相处的','让人愿意靠近，说几句话也不会感到拘谨。','经古法语 amiable 来自晚期拉丁 amicabilis；法语阶段又与 amable“可爱的”发生形式和意义上的影响。不是英语 am + able。',A+[['晚期拉丁 amicabilis → 古法语 amiable','友好的；同时受“可爱的”一支影响'],['英语 amiable','和善、亲切、令人愉快的']],'an amiable host 是让客人放松的主人，an amiable smile 是友好的微笑。amiable 不等于没原则：一个人可以态度和善，同时清楚拒绝不合理要求。与 amicable 的同源关系真实存在，但两个词如今最自然的搭配不完全一样。','an amiable person；an amiable smile；an amiable host。','amiable 首音节 /eɪ/，amicable 首音节 /æ/；前者常说人好相处，后者常说双方相处或解决事情很和睦。',('Our host was amiable and made everyone feel at ease.','主人很亲切，让每个人都感到自在。'),('She gave an amiable smile but declined the invitation.','她友好地笑了笑，但谢绝了邀请。'),sources=['https://www.etymonline.com/word/amiable','https://www.merriam-webster.com/dictionary/amiable']),
E('amiably','/ˈeɪmiəbli/','亲切地、和善地','说话和举止都带着让人放松的善意。','amiable 去末尾 e 加 -ly，变成描述行为方式的副词。',A+[['英语 amiable → amiably','亲切的 → 亲切地']],'chat amiably 是轻松友好地聊天，smile amiably 是和善地微笑。它特别适合近距离的人际互动：你能想象对方的语气和表情，而不是一份协议上抽象的友好关系。','chat amiably；smile amiably；remark amiably。','amicably 常说双方把事情友好处理好；amiably 常说某个人的表现亲切。',('The driver chatted amiably with the passengers.','司机亲切地和乘客聊天。'),('“Take your time,” she said amiably.','“慢慢来，”她和善地说。'),sources=['https://en.wiktionary.org/wiki/amiably','https://www.merriam-webster.com/dictionary/amiable']),
E('amity','/ˈæməti/','友好、和睦关系〔正式〕','双方能够友善共处，不把彼此当成威胁。','经古法语 amitié／amistie 接通俗拉丁 amicitas 一支，与拉丁 amicitia“友谊”、amicus“朋友”相关。',A+[['拉丁 amicitia／通俗拉丁同族形式 → 古法语 amitié','友谊、友好关系'],['英语 amity','和睦、友好关系']],'amity 常见于国家、群体或正式叙述中的友好关系。live in amity 就是和睦共处；日常说“我和他的友谊”，通常用 friendship 更自然，不必为了用词高级处处换成 amity。','in amity；amity between；a spirit of amity。','amity 表友好，enmity 表敌意，放在一起很适合记忆。读音也不同：/ˈæməti/ 对 /ˈenməti/。',('The two communities lived in amity for generations.','这两个社区世世代代和睦相处。'),('The meeting ended in a spirit of amity and cooperation.','会议在友好合作的气氛中结束。'),sources=['https://www.etymonline.com/word/amity','https://en.wiktionary.org/wiki/amity']),
E('archenemy','/ˌɑːrtʃˈenəmi/','头号敌人、宿敌','众多对手里，那个最主要、最难摆脱的敌人。','英语 arch-“首要的、极端的”+ enemy；arch- 更早来自希腊表示首领、统领的词族，与建筑的 arch“拱”不是这里的构词解释。',N+[['古法语 enemi → 英语 enemy','敌人'],['英语 arch- + enemy → archenemy','首要的敌人、宿敌']],'小说里的英雄常有一个反复交锋的 archenemy。日常也会夸张地把总能让你失败的东西叫 archenemy，比如早起者眼里的贪睡按钮；语气由语境决定，不必按真正的仇恨理解。','someone’s archenemy；face an archenemy；become archenemies。','enemy 是一般敌人；archenemy 特别突出主要、长期或最强的对立者，不只是见过一次的比赛对手。',('The detective finally came face to face with her archenemy.','侦探终于与她的宿敌正面相遇。'),('In the comic, the hero’s archenemy returns with a new plan.','漫画里，英雄的头号敌人带着新计划卷土重来。'),sources=['https://en.wiktionary.org/wiki/archenemy','https://www.etymonline.com/word/archenemy'])]
ROOT=dict(id='C0041',meaning='爱、朋友；否定后成为敌对',core='AM / AMIC = LOVE / FRIEND',image='把一个人当朋友，关系就是友好的；加上“不”的历史成分，便走向敌对。现代 enemy 的敌意比简单的“不是朋友”强得多。',intro='拉丁 amare 是爱，amicus 是朋友、友好的。最容易用混的是 amiable 与 amicable：前者常说一个人亲切，后者常说双方关系或处理方式和睦。enemy 虽然拼写变了很多，仍能沿法语路线追到 in- + amicus。',forms='amic- 保留在 amicable 中，经法语变化后出现 amiable、amity。拉丁 in- + amicus 形成 inimicus，带来 inimical，也经法语变成 enemy。enmity 表敌意，与 amity 的友好形成对照。',branches=[['亲切好相处','amiable, amiably'],['和睦相处与解决分歧','amicable, amicably, amity'],['敌对与不利','enemy, archenemy, enmity, inimical']],contrasts='amiable 是人或表现亲切，amicable 常是关系、协商或结果和睦。amity 是友好，enmity 是敌意。opponent 不一定是 enemy；普通分歧也不等于 enmity。',practice='Our amiable host helped the neighbours settle the dispute amicably, without creating lasting enmity.\n\n亲切的主人帮助邻居们友好地解决了纠纷，没有留下长久的仇怨。',words=[w['word'] for w in W]+['inimical'],exclude={})
if __name__=='__main__':
 for name,data in [('roots_am',[ROOT]),('words_am',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(w['examples']) for w in W))
